const { createUser, ValidationError } = require('../users');

test('creates a user', () => {
  assert.deepStrictEqual(createUser({ name: 'Asha', age: 31 }), { name: 'Asha', age: 31 });
});

test('accepts a numeric string age and returns a number', () => {
  assert.deepStrictEqual(createUser({ name: 'Asha', age: '42' }), { name: 'Asha', age: 42 });
});

test('accepts the age bounds 0 and 150', () => {
  assert.strictEqual(createUser({ name: 'A', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'A', age: '150' }).age, 150);
});

test('rejects bad names', () => {
  for (const name of ['', '   ', null, undefined, 42]) {
    assert.throws(() => createUser({ name, age: 30 }), ValidationError);
  }
});

test('rejects bad ages', () => {
  for (const age of [-1, 151, 1.5, NaN, Infinity, '', ' ', '4.2', '1e2', '-3', 'abc', null, undefined, true]) {
    assert.throws(() => createUser({ name: 'Asha', age }), ValidationError, `age ${String(age)}`);
  }
});

test('rejects non-object input', () => {
  for (const input of [null, undefined, 'Asha']) {
    assert.throws(() => createUser(input), ValidationError);
  }
});

